-- 5. Tabela Temporária com Delta
CREATE TEMP TABLE temp_catalog_legacy_delta (
  code VARCHAR(150),
  name VARCHAR(200),
  normalized_name VARCHAR(200),
  normalized_brand VARCHAR(150),
  normalized_serie VARCHAR(150),
  scale_ratio VARCHAR(20),
  release_year SMALLINT,
  line_type VARCHAR(50),
  photo_url VARCHAR(1000),
  identifier_type VARCHAR(50)
) ON COMMIT DROP;


-- 6. Atualizar Variações Já Existentes no Banco
UPDATE variation v
SET
  photo_url = COALESCE(t.photo_url, v.photo_url),
  line_type = COALESCE(t.line_type, v.line_type),
  series_id = COALESCE(s.id, v.series_id),
  scale_id = COALESCE(sc.id, v.scale_id),
  release_year = COALESCE(t.release_year, v.release_year)
FROM temp_catalog_legacy_delta t
JOIN product_identifier pi ON upper(trim(pi.code)) = upper(trim(t.code))
JOIN miniature_brand b ON b.normalized_name = t.normalized_brand
LEFT JOIN series s ON s.miniature_brand_id = b.id AND s.normalized_name = t.normalized_serie
LEFT JOIN scale sc ON sc.name = t.scale_ratio
WHERE v.id = pi.variation_id;

-- 7. Inserir Castings Inéditos
SELECT DISTINCT ON (b.id, t.normalized_name) b.id, t.name, t.normalized_name, false, 'ACTIVE'
FROM temp_catalog_legacy_delta t
JOIN miniature_brand b ON b.normalized_name = t.normalized_brand
WHERE NOT EXISTS (
  SELECT 1 FROM product_identifier pi WHERE upper(trim(pi.code)) = upper(trim(t.code))
)
ORDER BY b.id, t.normalized_name
ON CONFLICT (miniature_brand_id, normalized_name) DO UPDATE SET name = EXCLUDED.name;

-- 8. Inserir Novas Variações e seus respectivos Product Identifiers
WITH new_items AS (
  SELECT DISTINCT ON (upper(trim(t.code)))
    gen_random_uuid() as new_var_id,
    c.id as casting_id,
    s.id as series_id,
    COALESCE(sc.id, (SELECT id FROM scale WHERE numerator = 1 AND denominator = 64 LIMIT 1)) as scale_id,
    it.id as identifier_type_id,
    t.name,
    t.release_year,
    t.line_type,
    t.photo_url,
    upper(trim(t.code)) as code
  FROM temp_catalog_legacy_delta t
  JOIN miniature_brand b ON b.normalized_name = t.normalized_brand
  JOIN casting c ON c.miniature_brand_id = b.id AND c.normalized_name = t.normalized_name
  LEFT JOIN series s ON s.miniature_brand_id = b.id AND s.normalized_name = t.normalized_serie
  LEFT JOIN scale sc ON sc.name = t.scale_ratio
  JOIN identifier_type it ON it.code = t.identifier_type
  WHERE NOT EXISTS (
    SELECT 1 FROM product_identifier pi WHERE upper(trim(pi.code)) = upper(trim(t.code))
  )
  ORDER BY upper(trim(t.code))
),
ins_vars AS (
  SELECT new_var_id, casting_id, series_id, scale_id, name, release_year, line_type, photo_url, 'ACTIVE'
  FROM new_items
  ON CONFLICT (id) DO NOTHING
  RETURNING id
)
SELECT n.new_var_id, n.identifier_type_id, n.code, n.code, true
FROM new_items n
ON CONFLICT (identifier_type_id, normalized_code) DO NOTHING;

COMMIT;
